class GenericRuSerialLogsCollector(GenericBts):
    # In the future we could move to moler devices(when USB MUMIN will be out of use)
    # https://wrgitlab.ext.net.nokia.com/RAN/resource-packages/taf.rfrl.procedures/-/merge_requests/367/diffs
    # https://wrgitlab.int.net.nokia.com/RAN/resource-packages/taf.rfrl.bts/-/merge_requests/355/diffs
    #       Remember to delete old snap logs at the beginning of the test
    #       Add generating Moler devices based on lmi params

    def __init__(self, bts_type='GNB'):
        """
        Constructor of GenericRuSerialLogsCollector class.
        :param bts_type: BTS type
        """
        super(GenericRuSerialLogsCollector, self).__init__(bts_type=bts_type)
        self.rmi = rmod_serial_interface()
        self.ru_operations = GnbRuOperations() if bts_type == 'GNB' else EnbRuOperations()

    def setup_hosts_for_all_ru_console_collection(self, bts_id=0, du_id=0, skip_if_lmi_not_configured=True):
        """
        Setup hosts for all RUs.
            If skip_if_lmi_not_configured is set to True, it will skip the RU setup if LMI is not configured
            in other case it will raise an exception.
        :param bts_id: BTS ID
        :param du_id: DU ID
        :param skip_if_lmi_not_configured: Skip if LMI is not configured
        """
        all_radios = get_count_of_radios(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        for ru_id in range(all_radios):
            try:
                self.setup_host_for_ru_console_collection(bts_id=bts_id, du_id=du_id, ru_id=ru_id)
            except LMINotConfigured as e:
                if not skip_if_lmi_not_configured:
                    raise e
                logging.debug(f"Skipping RU setup due to LMI not configured, Details {e}")

    def setup_serial_console_connection_for_all_rus(self, bts_id=0, du_id=0, skip_if_lmi_not_configured=True,
                                                    raise_exception=True, remove_all_snapshots=False):
        """
        Start serial console logs collection for all RUs.
            If skip_if_lmi_not_configured is set to True, it will skip the RU setup if LMI is not configured
            in other case it will raise an exception.
        :param bts_id: BTS ID
        :param du_id: DU ID
        :param skip_if_lmi_not_configured: Skip if LMI is not configured
        :param raise_exception: Raise exception if setup ru console connection fails
        :param remove_all_snapshots: Remove all snapshots from '/mnt/runtime/'
        """
        all_radios = get_count_of_radios(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        for ru_id in range(all_radios):
            try:
                self.setup_ru_serial_console_connection(bts_id=bts_id, du_id=du_id, ru_id=ru_id,
                                                        remove_all_snapshots=remove_all_snapshots)
            except (ConnectionRefusedError, PyroSerializableError, ServerVersionMismatch) as e:
                if raise_exception:
                    raise e
                logging.warning(f"Failed to setup RU console connection for bts_id: {bts_id}, du_id: {du_id}, "
                                f"ru_id: {ru_id}, Details: {e}")
            except LMINotConfigured as e:
                if not skip_if_lmi_not_configured:
                    raise e
                logging.debug(f"Skipping RU setup due to LMI not configured, Details {e}")

    def setup_host_for_ru_console_collection(self, bts_id=0, du_id=0, ru_id=0, common_unit_id=None,
                                             capacity_unit_id=None, port='9092', remote_dir='C:/rsi',
                                             python_path='python', upload=True):
        """
        Setup host for RU.
            If LMI is not configured for RU, it will raise an exception.
        :param bts_id: BTS ID
        :param du_id: DU ID
        :param ru_id: RU ID
        :param common_unit_id: Common Unit ID
        :param capacity_unit_id: Capacity Unit ID
        :param str port:  port on which Pyro4 server will listen for connections. Defaults to 9092
        :param str remote_dir:  directory on host machine to which all server files will be copied.
                                Defaults to 'C:/rsi'
        :param str python_path:  path to python executable on host machine which will be used to run server.
                                 Defaults to 'python'.
        :param bool upload:  Specifies whether to upload server files to host before attempting
                             connection. Required when running for the first time (when server
                             files are not yet on host machine) or if we want to automatically
                             upload newer version. Disable to save some time. Defaults to True

        :return
        """
        ru = get_radio(bts_id, du_id, ru_id, self.bts_type, common_unit_id, capacity_unit_id)
        lmi = ru.lmi
        if lmi is None:
            raise LMINotConfigured(f"LMI is not configured for RU under bts_id: "
                                   f"{bts_id}, du_id: {du_id}, ru_id: {ru_id}")
        try:
            self.rmi._setup_host_from_ru_config(lmi, alias=None, port=port, remote_dir=remote_dir,
                                                python_path=python_path, upload=upload)
        except ServerVersionMismatch as e:
            logging.warning(f"Failed due to server version mismatch: {e}. "
                            f"Automatic server upgrade functionality has been requested from library authors")

    def setup_ru_serial_console_connection(self, bts_id=0, du_id=0, ru_id=0, common_unit_id=None, capacity_unit_id=None,
                                           ru_alias=None, remove_all_snapshots=False):
        """
        Setup serial console logs connection for RU.
            If LMI is not configured for RU, it will raise an exception.
            You can pass ru_alias to setup connection with custom alias name - if not passed,
            it will be generated based on bts/du/ru/common_unit/capacity ids
        :param bts_id: BTS ID
        :param du_id: DU ID
        :param ru_id: RU ID
        :param common_unit_id: Common Unit ID
        :param capacity_unit_id: Capacity Unit ID
        :param ru_alias: RU Alias
        :param remove_all_snapshots: remove all snapshots from '/mnt/runtime/'
        :return
        """
        ru = get_radio(bts_id, du_id, ru_id, self.bts_type, common_unit_id, capacity_unit_id)
        conf_sn = ru.serial_number
        lmi = ru.lmi

        if ru_alias is None:
            ru_alias = self._build_lmi_ru_alias(bts_id, du_id, ru_id, common_unit_id, capacity_unit_id)

        if lmi is None:
            raise LMINotConfigured(f"LMI is not configured for {ru_alias}")

        logging.debug(f"Setting up RU serial console connection for {ru_alias}")
        self.rmi.setup_rmod_connection_from_ru_config(ru_config=ru, alias=ru_alias, use_init_credentials=True)

        collected_sn = self.rmi.get_rmod_serial_number(ru_alias)
        if collected_sn != conf_sn:
            raise WrongSerialNumber(f"Serial number from configuration file: {conf_sn} is different than collected "
                                    f"from console {collected_sn}. Please check your configuration file.")
        if remove_all_snapshots:
            self.remove_all_snapshots(ru_alias=ru_alias)

    def set_swconfig_to_collect_ru_syslog_for_all_rus(self, bts_id=0, du_id=0, skip_if_lmi_not_configured=True):
        """
        Set SWCONFIG to collect RU syslog for all RUs.
        :param bts_id: BTS ID
        :param du_id: DU ID
        :param skip_if_lmi_not_configured: Skip if LMI is not configured
        :param ru_timeout: timeout for waiting for RU to be online
        :param cells_timeout: timeout for waiting for cells to be onair
        """
        all_radios = get_count_of_radios(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        for ru_id in range(all_radios):
            try:
                self.set_swconfig_to_collect_ru_syslog(bts_id=bts_id, du_id=du_id, ru_id=ru_id)
            except LMINotConfigured as e:
                if not skip_if_lmi_not_configured:
                    raise e
                logging.debug(f"Skipping RU swconfig setup due to LMI not configured for syslog, Details: {e}")

    def start_streaming_syslog_on_ru_for_all_rus(self, bts_id=0, du_id=0, skip_if_lmi_not_configured=True):
        """
        Start streaming syslog on RU for all RUs
        :param bts_id: BTS ID
        :param du_id: DU ID
        :param skip_if_lmi_not_configured: Skip if LMI is not configured
        """
        all_radios = get_count_of_radios(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        for ru_id in range(all_radios):
            try:
                self.start_streaming_syslog_on_ru(bts_id=bts_id, du_id=du_id, ru_id=ru_id)
            except LMINotConfigured as e:
                if not skip_if_lmi_not_configured:
                    raise e
                logging.debug(f"Skipping RU syslog startup due to LMI not configured for syslog, Details: {e}")

    def set_swconfig_to_collect_ru_syslog(self, bts_id=0, du_id=0, ru_id=0, common_unit_id=None, capacity_unit_id=None,
                                          ru_alias=None):
        """
        Set SWCONFIG to collect RU syslog
        :param bts_id: BTS ID
        :param du_id: DU ID
        :param ru_id: RU ID
        :param common_unit_id: Common Unit ID
        :param capacity_unit_id: Capacity Unit ID
        :param ru_alias: RU Alias - if not passed then will be generated based on bts/du/ru/common_unit/capacity ids
        """
        ru = get_radio(bts_id, du_id, ru_id, self.bts_type, common_unit_id, capacity_unit_id)
        if ru.lmi is None or ru.lmp_connection is None:
            raise LMINotConfigured(f"LMI or RU lmp connection is not configured to collect syslog for RU under bts_id: "
                                   f"{bts_id}, du_id: {du_id}, ru_id: {ru_id}")

        if ru_alias is None:
            ru_alias = self._build_lmi_ru_alias(bts_id, du_id, ru_id, common_unit_id, capacity_unit_id)

        vm_eth1_addr = self._get_interface_address_to_collect_syslog(ru_id)
        vm_eth1_hex_addr = self._convert_ip_address_to_hex(vm_eth1_addr)
        swconfig_flags = ['0x10041=2', '0x10042=' + vm_eth1_hex_addr, '0x10043=51001', '0x10045=15728640']
        cat_cmd = "cat <<EOT > /rom/swconfig.txt\n" + "\n".join(swconfig_flags) + "\nEOT"
        self.rmi.send_command(cmd=cat_cmd, alias=ru_alias)
        self.rmi.send_command(cmd="reboot", alias=ru_alias)
        self.ru_operations.wait_for_radio_unit_statuses(bts_id=bts_id, du_id=du_id, ru_id=ru_id + 1,
                                                        operational_state='disabled', timeout=30, interval=1)

    def start_streaming_syslog_on_ru(self, bts_id=0, du_id=0, ru_id=0, common_unit_id=None, capacity_unit_id=None,
                                     ru_alias=None):
        """
        Start streaming syslog on RU
        :param bts_id: BTS ID
        :param du_id: DU ID
        :param ru_id: RU ID
        :param common_unit_id: Common Unit ID
        :param capacity_unit_id: Capacity Unit ID
        :param ru_alias: RU Alias - if not passed then will be generated based on bts/du/ru/common_unit/capacity ids
        """
        ru = get_radio(bts_id, du_id, ru_id, self.bts_type, common_unit_id, capacity_unit_id)
        if ru.lmi is None or ru.lmp_connection is None:
            raise LMINotConfigured(f"LMI or RU lmp connection is not configured to collect syslog for RU under bts_id: "
                                   f"{bts_id}, du_id: {du_id}, ru_id: {ru_id}")

        if ru_alias is None:
            ru_alias = self._build_lmi_ru_alias(bts_id, du_id, ru_id, common_unit_id, capacity_unit_id)
        self.rmi.send_command(cmd="sudo lmi-eth on", alias=ru_alias)

    def _build_lmi_ru_alias(self, bts_id=0, du_id=0, ru_id=0, common_unit_id=None, capacity_unit_id=None):
        # GNB0_DU0_RU0_LMI
        # GNB0_DU0_CU0_RU0_LMI
        # GNB0_DU0_CU0_CPTY0_RU0_LMI
        alias = f"{self.bts_type}{bts_id}_DU{du_id}"
        if common_unit_id is not None:
            alias += f"_CU{common_unit_id}"
            if capacity_unit_id is not None:
                alias += f"_CPTY{capacity_unit_id}"
        alias += f"_RU{ru_id}_LMI"
        return alias

    def _extract_ids_from_ru_alias(self, ru_alias):
        # GNB0_DU0_RU0_LMI
        # GNB0_DU0_CU0_RU0_LMI
        # GNB0_DU0_CU0_CPTY0_RU0_LMI
        id_regex = re.compile(r'[EG]NB(?P<bts_id>\d+)_DU(?P<du_id>\d+)(?:_CU(?P<common_unit_id>\d+)'
                              r'(?:_CPTY(?P<capacity_unit_id>\d+))?)?_RU(?P<ru_id>\d+)_LMI')
        match = id_regex.match(ru_alias)
        return match.groupdict()

    @load_moler_configuration_from_tl()
    def _get_interface_address_to_collect_syslog(self, ru_id):
        ru_ws_name = get_devices_from_regex(pattern=self.ws_ru_pattern.format(ru_id))[0]
        ru_ws = DeviceFactory.get_device(name=ru_ws_name)
        get_ip_addr_cmd = ru_ws.get_cmd(cmd_name="ip_addr", cmd_params={"options": "show"})
        ru_ws_ip_addr = get_ip_addr_cmd()
        eth1_ip = ru_ws_ip_addr["eth1"]["IPV4"][0]["IP"]
        return eth1_ip

    def _convert_ip_address_to_hex(self, ip_address):
        splitted_ip_address = ip_address.split('.')
        return '0x{:02X}{:02X}{:02X}{:02X}'.format(*map(int, splitted_ip_address))

    def collect_console_log_from_all_setup_rus(self, log_dir=None):
        """
        Collect console logs from all RUs.
        :param log_dir: Directory to save logs
        """
        for ru_alias in self.rmi._rmod_to_client_map:
            self.collect_ru_console_log(ru_alias=ru_alias, log_dir=log_dir)

    def collect_ru_console_log(self, bts_id=0, du_id=0, ru_id=0, common_unit_id=None, capacity_unit_id=None,
                               log_dir=None, ru_alias=None):
        """
        Collect console logs from RU.
            You can pass ru_alias to setup connection with custom alias name - if not passed,
            it will be generated based on bts/du/ru/common_unit/capacity ids
        :param bts_id: BTS ID
        :param du_id: DU ID
        :param ru_id: RU ID
        :param common_unit_id: Common Unit ID
        :param capacity_unit_id: Capacity Unit ID
        :param log_dir: Directory to save logs
        :param ru_alias: RU Alias
        :return: File Path of collected log
        """
        if log_dir is None:
            log_dir = get_log_path()
        if ru_alias is None:
            ru_alias = self._build_lmi_ru_alias(bts_id, du_id, ru_id, common_unit_id, capacity_unit_id)
        logging.debug(f"Collecting console log from {ru_alias}")
        sn = self.rmi.get_rmod_serial_number(ru_alias)
        file_name = f"{ru_alias}_{sn}_console_log.txt"
        log_dir = os.path.join(log_dir, 'RMOD')
        os.makedirs(log_dir, exist_ok=True)
        file_path = os.path.join(log_dir, file_name)
        self.rmi.download_log(local_path=file_path, alias=ru_alias)
        logging.debug(f"[{ru_alias}] Console log collected: {file_path}")
        return file_path

    def collect_ru_snapshot(self, bts_id=0, du_id=0, ru_id=0, common_unit_id=None, capacity_unit_id=None,
                            ru_alias=None, log_dir=None, remove_source_file=True):
        """
        Collect snapshot from RU.
            You can pass ru_alias to setup connection with custom alias name - if not passed,
            it will be generated based on bts/du/ru/common_unit/capacity ids
        :param bts_id: BTS ID
        :param du_id: DU ID
        :param ru_id: RU ID
        :param common_unit_id: Common Unit ID
        :param capacity_unit_id: Capacity Unit ID
        :param ru_alias: RU Alias
        :param log_dir: Directory to save logs
        :param remove_source_file: Remove source file from RU after download
        :return: Snapshot Path
        """
        if ru_alias is None:
            device_ids = {'bts_id': bts_id, 'du_id': du_id, 'ru_id': ru_id,
                          'common_unit_id': common_unit_id, 'capacity_unit_id': capacity_unit_id}
            ru_alias = self._build_lmi_ru_alias(bts_id, du_id, ru_id, common_unit_id, capacity_unit_id)
        else:
            device_ids = self._extract_ids_from_ru_alias(ru_alias)

        logging.debug(f"[{ru_alias}] Collecting snapshot ...")
        download_from_ram = False
        snap_exception = None
        try:
            snapshot_path = self.rmi.take_snapshot(alias=ru_alias)
            snapshot_path_for_download = snapshot_path
            logging.debug(f"[{ru_alias}] Snapshot collected in: {snapshot_path}")
        except ROMMemoryFullError as e:
            snap_exception = e
            download_from_ram = True
        except TimeoutError as e:
            snap_exception = e
            if "while moving snapshot file from /ram/" in str(e):
                download_from_ram = True
            else:
                raise e
        try:
            if download_from_ram:
                snapshot_path_for_download = r"/ram/snapshot.*\.zip"
                snapshot_path = r"/ram/snapshot*.zip"
                logging.warning(f"[{ru_alias}] Moving snapshot to /mnt/runtime/ failed.")
                formatted_exception = ''.join(traceback.format_exception(type(snap_exception), snap_exception,
                                                                         snap_exception.__traceback__))
                logging.debug(f"Details: {formatted_exception}")
                logging.debug(f"[{ru_alias}] Try to downloading directly from '/ram/' directory ")

            local_snapshot_path = self._download_ru_snapshot(remote_file=snapshot_path_for_download, log_dir=log_dir,
                                                             use_regex=download_from_ram, **device_ids)
            if remove_source_file:
                logging.debug(f"[{ru_alias}] Removing source snapshot file from RU: {snapshot_path}")
                self.remove_all_snapshots(ru_alias=ru_alias, cleanup_dir=os.path.dirname(snapshot_path),
                                          file_pattern=os.path.basename(snapshot_path))
            return local_snapshot_path
        except Exception as e:
            logging.warning(
                f"[{ru_alias}] Cannot download RU snapshot to local machine. "
                f"Most probably BTS has no connection to RU. Snapshot is still available on RU at [{snapshot_path}].\n"
                f"THE LOCATION [/mnt/runtime/] HAS LIMITED SPACE. "
                f"LEAVING THE SNAPSHOT THERE MAY RESULT IN INSUFFICIENT SPACE FOR FUTURE SNAPSHOTS, CAUSE RU "
                f"MALFUNCTION, OR EVEN BLOCK RU UPGRADES. AFTER MANUALLY COPYING THE SNAPSHOT, "
                f"PLEASE REMOVE IT FROM [/mnt/runtime/]."
            )
            logging.debug(f"[{ru_alias}] Details: {e}")

        return snapshot_path

    def collect_snapshot_from_all_setup_rus(self, log_dir=None, remove_source_file=True):
        """
        Collect snapshot from all RUs.
        """

        list_of_functions = []
        for ru_alias in self.rmi._rmod_to_client_map:
            list_of_functions.append(
                {
                    'function': self.collect_ru_snapshot,
                    'function_kwargs': {'ru_alias': ru_alias, 'log_dir': log_dir,
                                        'remove_source_file': remove_source_file},
                    'device_name': ru_alias,
                    'raise_exception': True
                }
            )

        logging.info("Start collecting snapshot from all RUs")
        raw_results = run_parallel_in_robot(list_of_functions)
        results = {name.split("::")[1]: raw_results[name] for name in raw_results.keys()}

        return results

    @load_moler_configuration_from_tl()
    def _download_ru_snapshot(self, remote_file, bts_id=0, du_id=0, ru_id=0,
                              common_unit_id=None, capacity_unit_id=None, log_dir=None, use_regex=False):
        """
        Collect ccsShell logs from RU
        :param remote_file:  Remote file path on RU
        :param bts_id:  BTS id - related to Test Line configuration. Default: 0
        :param du_id:   DU id(Distributed Unit) - id related to Test Line configuration. Default: 0
        :param ru_id:   Position of RU in rus table from Test Line configuration. If None - run on all rus
        :param common_unit_id: Common Unit ID
        :param capacity_unit_id: Capacity Unit ID
        :param log_dir: local directory path where logs will be downloaded.
                        If None - default logs dir will be used: ${OUTPUT DIR}/Logs/<timestamp>
        """
        device = self.ru_operations.get_ru_device(bts_id=bts_id, du_id=du_id, ru_id=ru_id)
        if log_dir is None:
            log_dir = get_log_path()
        log_dir = os.path.join(log_dir, 'RMOD')
        local_file_location = os.path.join(log_dir, os.path.basename(remote_file))
        remote_file_name = os.path.basename(remote_file) if not use_regex else rf"/{os.path.basename(remote_file)}/"
        new_file_name = f"{device.name}_{remote_file_name}" if not use_regex else None
        download_files(local_dir=log_dir,
                       remote_file=remote_file_name,
                       remote_dir=os.path.dirname(remote_file),
                       device_name=self.ssh_ru_alias.format(bts_id, du_id, ru_id),
                       new_file_name=new_file_name,
                       timeout=60)
        return local_file_location

    def remove_all_snapshots(self, bts_id=0, du_id=0, ru_id=0, common_unit_id=None, capacity_unit_id=None,
                             ru_alias=None, cleanup_dir='/mnt/runtime/', file_pattern='snapshot_*.zip'):
        """
        Clean old snapshots on RU.
            You can pass ru_alias to setup connection with custom alias name - if not passed,
            it will be generated based on bts/du/ru/common_unit/capacity ids
        :param bts_id: BTS ID
        :param du_id: DU ID
        :param ru_id: RU ID
        :param common_unit_id: Common Unit ID
        :param capacity_unit_id: Capacity Unit ID
        :param ru_alias: RU Alias
        :param cleanup_dir: Directory on RU to clean old snapshots
        :param file_pattern: File pattern to match snapshots
        """

        if ru_alias is None:
            ru_alias = self._build_lmi_ru_alias(bts_id, du_id, ru_id, common_unit_id, capacity_unit_id)

        path_to_remove = posixpath.join(cleanup_dir, file_pattern)
        logging.debug(f"[{ru_alias}] Remove all snapshots located in '{path_to_remove}' ...")
        cmd = f"rm -f {path_to_remove}"
        results = self.rmi.execute_command('whoami', alias=ru_alias)
        if 'serviceuser' in results:
            cmd = f"sudo -u rfsw {cmd}"

        self.rmi.send_command(cmd=cmd, alias=ru_alias)

    def teardown_ru_serial_console_connection(self, bts_id=0, du_id=0, ru_id=0, common_unit_id=None,
                                              capacity_unit_id=None,
                                              ru_alias=None):
        """
        Teardown serial console logs collector for RU.
            If LMI is not configured for RU, it will raise an exception.
            You can pass ru_alias to setup connection with custom alias name - if not passed,
            it will be generated based on bts/du/ru/common_unit/capacity ids
        :param bts_id: BTS ID
        :param du_id: DU ID
        :param ru_id: RU ID
        :param common_unit_id: Common Unit ID
        :param capacity_unit_id: Capacity Unit ID
        :param ru_alias: RU Alias
        :return
        """
        if ru_alias is None:
            ru_alias = self._build_lmi_ru_alias(bts_id, du_id, ru_id, common_unit_id, capacity_unit_id)
        logging.debug(f"Teardown RU serial console connection for {ru_alias}")
        self.rmi.teardown(alias=ru_alias)

    def teardown_serial_console_connection_for_all_setup_rus(self):
        aliases = list(self.rmi._rmod_to_client_map.keys())
        for ru_alias in aliases:
            self.teardown_ru_serial_console_connection(ru_alias=ru_alias)

    def teardown_hosts_for_all_ru_console_collection(self):
        self.rmi.teardown_all_hosts()


@six.add_metaclass(Singleton)
class EnbRuSerialLogsCollector(GenericRuSerialLogsCollector):
    """Class contains RU(Radio Unit) keywords for eNB"""

    bts_type = 'ENB'

    def __init__(self):
        """
        Constructor of Enb class.

        """
        super(EnbRuSerialLogsCollector, self).__init__(bts_type=EnbRuSerialLogsCollector.bts_type)


